import sys
from collections import Counter

def solve():
    s = sys.stdin.readline().strip()

    if not s:
        print(0)
        return

    freq = Counter(s)
    unique_chars = list(freq.keys())

    if len(unique_chars) < 2:
        print(0)
        return

    max_length = 0

    for i in range(len(unique_chars)):
        for j in range(len(unique_chars)):
            if i == j:
                continue

            char1 = unique_chars[i]
            char2 = unique_chars[j]

            length = 0
            expected = char1

            for c in s:
                if c == char1 or c == char2:
                    if c == expected:
                        length += 1
                        expected = char2 if expected == char1 else char1

            if length > max_length:
                max_length = length

    print(max_length)

if __name__ == "__main__":
    solve()
